namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    [StringLength(500)]
    public string? Notes { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CourseCatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CourseCatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and data analysis." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and communication studies." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Fundamental principles of matter, energy, and the universe." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events, civilizations, and historical analysis." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor", Bio = "Expert in algorithms and programming languages with 15 years of teaching experience. Published over 40 research papers on computational theory.", Email = "alovelace@university.edu" },
            new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor", Bio = "Specializes in artificial intelligence and machine learning. Former industry researcher at leading tech companies.", Email = "aturing@university.edu" },
            new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Renowned mathematician specializing in abstract algebra and theoretical physics. Recipient of the Distinguished Teaching Award.", Email = "enoether@university.edu" },
            new() { Id = 4, Name = "Dr. William Shakespeare", Title = "Professor", Bio = "Award-winning author and literary critic with expertise in Renaissance literature and creative writing.", Email = "wshakespeare@university.edu" },
            new() { Id = 5, Name = "Dr. Marie Curie", Title = "Professor", Bio = "Pioneer in experimental physics with a focus on radioactivity and nuclear science. Two-time Nobel laureate.", Email = "mcurie@university.edu" },
            new() { Id = 6, Name = "Dr. Howard Zinn", Title = "Associate Professor", Bio = "Social historian specializing in American civil rights movements and labor history.", Email = "hzinn@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering the fundamentals of programming, data structures, and algorithmic thinking. Students will learn Python and build several small projects.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "Advanced study of data structures including trees, graphs, and hash tables. Covers algorithm design and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Code = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and practical applications using Python.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Location = "Tech Center 110", DepartmentId = 1, InstructorId = 2, IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, and eigenvalues. Essential for students in mathematics, physics, and computer science.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Math Building 102", DepartmentId = 2, InstructorId = 3 },
            new() { Id = 5, Code = "MATH 301", Title = "Abstract Algebra", Description = "Introduction to algebraic structures including groups, rings, and fields with emphasis on proof techniques.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Location = "Math Building 204", DepartmentId = 2, InstructorId = 3, IsFeatured = true },
            new() { Id = 6, Code = "ENG 101", Title = "College Writing", Description = "Develop essential writing skills including argumentation, research methods, and academic discourse. Emphasis on clear, effective communication.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Humanities 101", DepartmentId = 3, InstructorId = 4 },
            new() { Id = 7, Code = "ENG 350", Title = "Shakespeare Studies", Description = "In-depth analysis of Shakespeare's major works including tragedies, comedies, and histories. Explores themes, language, and cultural context.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", Location = "Humanities 203", DepartmentId = 3, InstructorId = 4 },
            new() { Id = 8, Code = "PHYS 201", Title = "Classical Mechanics", Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations. Covers motion, energy, momentum, and rotational dynamics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Physics Lab 101", DepartmentId = 4, InstructorId = 5, IsFeatured = true },
            new() { Id = 9, Code = "PHYS 310", Title = "Quantum Physics", Description = "Introduction to quantum mechanics: wave-particle duality, Schrödinger equation, and applications to atomic and molecular systems.", Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM", Location = "Physics Lab 202", DepartmentId = 4, InstructorId = 5 },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from antiquity through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 9:00–10:15 AM", Location = "Liberal Arts 301", DepartmentId = 5, InstructorId = 6 },
            new() { Id = 11, Code = "HIST 250", Title = "Modern American History", Description = "American history from the Civil War to the present, covering industrialization, civil rights, and contemporary issues.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", Location = "Liberal Arts 205", DepartmentId = 5, InstructorId = 6 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public Department? GetDepartmentForCourse(int courseId)
    {
        var course = GetCourse(courseId);
        return course is null ? null : GetDepartment(course.DepartmentId);
    }
}

