    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.GetCourses(Search, DepartmentId);
        _selectedDepartment = DepartmentId.HasValue ? Catalog.GetDepartment(DepartmentId.Value) : null;
    }
}

