@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CourseCatalogService Catalog

<PageTitle>Enrollment Request – University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for
                <strong>@_selectedCourseName</strong> has been received.</p>
            <p class="mb-0">You will receive a confirmation at your university email. Student ID: @_model.StudentId</p>
        </div>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        <a href="/enroll" class="btn btn-outline-secondary ms-2">Submit Another Request</a>
    }
    else
    {
        <div class="row">
            <div class="col-lg-8">
                <form method="post" data-enhance>
                    <AntiforgeryToken />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input type="text" id="studentName" name="Model.StudentName" value="@_model.StudentName"
                               class="form-control" required maxlength="100" />
                        @if (_errors.ContainsKey(nameof(_model.StudentName)))
                        {
                            <div class="text-danger small mt-1">@_errors[nameof(_model.StudentName)]</div>
                        }
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                        <input type="text" id="studentId" name="Model.StudentId" value="@_model.StudentId"
                               class="form-control" required maxlength="20" placeholder="e.g. STU-12345" />
                        @if (_errors.ContainsKey(nameof(_model.StudentId)))
                        {
                            <div class="text-danger small mt-1">@_errors[nameof(_model.StudentId)]</div>
                        }
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                        <select id="courseId" name="Model.CourseId" class="form-select" required>
                            <option value="">— Select a course —</option>
                            @foreach (var course in _courses)
                            {
                                <option value="@course.Id" selected="@(course.Id == _model.CourseId)">
                                    @course.Code – @course.Title (@course.Credits cr.)
                                </option>
                            }
                        </select>
                        @if (_errors.ContainsKey(nameof(_model.CourseId)))
                        {
                            <div class="text-danger small mt-1">@_errors[nameof(_model.CourseId)]</div>
                        }
                    </div>

                    <div class="mb-3">
                        <label for="notes" class="form-label">Additional Notes</label>
                        <textarea id="notes" name="Model.Notes" class="form-control" rows="3"
                                  maxlength="500">@_model.Notes</textarea>
                    </div>

                    <button type="submit" class="btn btn-success btn-lg">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-outline-secondary btn-lg ms-2">Cancel</a>
                </form>
            </div>
            <div class="col-lg-4 mt-4 mt-lg-0">
                <div class="card bg-light">
                    <div class="card-body">
                        <h5 class="card-title">ℹ️ How It Works</h5>
                        <ol class="mb-0 ps-3">
                            <li>Fill out the form with your details</li>
                            <li>Select the course you wish to enroll in</li>
                            <li>Submit your request</li>
                            <li>The registrar will review and confirm via email</li>
                        </ol>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private EnrollmentRequest _model = new();
    private List<Course> _courses = new();
    private bool _submitted;
    private string _selectedCourseName = string.Empty;
    private Dictionary<string, string> _errors = new();

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();
        _model = Model;

        if (CourseId.HasValue && _model.CourseId == 0)
            _model.CourseId = CourseId.Value;
    }

    protected override void OnParametersSet()
    {
        if (!HttpMethods.IsPost(string.Empty))
            return;

        _errors.Clear();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(_model);
        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(_model, context, results, true))
        {
            foreach (var r in results)
            {
                foreach (var member in r.MemberNames)
                {
                    _errors.TryAdd(member, r.ErrorMessage ?? "Invalid");
                }
            }
            return;
        }

        var course = Catalog.GetCourse(_model.CourseId);
        _selectedCourseName = course is not null ? $"{course.Code} – {course.Title}" : "Unknown Course";
        _submitted = true;
    }
}

