@page "/courses"
@using CourseCatalog.Services
@inject CourseCatalogService Catalog

<PageTitle>Courses – University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Courses</h1>

    <form method="get" class="row g-3 mb-4" data-enhance>
        <div class="col-md-6">
            <label for="search" class="form-label">Search</label>
            <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or keyword…" />
        </div>
        <div class="col-md-4">
            <label for="departmentId" class="form-label">Department</label>
            <select id="departmentId" name="departmentId" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in _departments)
                {
                    <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Code – @dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2 d-flex align-items-end">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </form>

    @if (_selectedDepartment is not null)
    {
        <div class="alert alert-info d-flex justify-content-between align-items-center">
            <span>Showing courses in <strong>@_selectedDepartment.Name</strong></span>
            <a href="/courses" class="btn btn-sm btn-outline-info">Clear Filter</a>
        </div>
    }

    @if (_courses.Count == 0)
    {
        <div class="alert alert-warning">No courses match your criteria. Try adjusting your search or filter.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Schedule</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in _courses)
                    {
                        var dept = Catalog.GetDepartmentForCourse(course.Id);
                        <tr>
                            <td><span class="badge bg-primary">@course.Code</span></td>
                            <td>@course.Title</td>
                            <td>@dept?.Name</td>
                            <td>@course.Credits</td>
                            <td class="small">@course.Schedule</td>
                            <td>
                                <a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-body-secondary">@_courses.Count course(s) found</p>
    }
</div>

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<CourseCatalog.Models.Course> _courses = new();
    private List<CourseCatalog.Models.Department> _departments = new();
    private CourseCatalog.Models.Department? _selectedDepartment;

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.GetCourses(Search, DepartmentId);
        _selectedDepartment = DepartmentId.HasValue ? Catalog.GetDepartment(DepartmentId.Value) : null;
    }
}

@page "/courses/{Id:int}"
@using CourseCatalog.Services
@inject CourseCatalogService Catalog

<PageTitle>@(_course?.Title ?? "Course Not Found") – University Course Catalog</PageTitle>

<div class="container py-4">
    @if (_course is null)
    {
        <div class="alert alert-danger">Course not found.</div>
        <a href="/courses" class="btn btn-outline-secondary">← Back to Courses</a>
    }
    else
    {
        <nav aria-label="breadcrumb" class="mb-3">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/courses?departmentId=@_department?.Id">@_department?.Name</a></li>
                <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
            </ol>
        </nav>

        <div class="row">
            <div class="col-lg-8">
                <h1>@_course.Title</h1>
                <span class="badge bg-primary fs-6 mb-3">@_course.Code</span>

                <p class="lead mt-3">@_course.Description</p>

                <h3 class="mt-4">Schedule &amp; Location</h3>
                <table class="table table-bordered w-auto">
                    <tbody>
                        <tr>
                            <th>Schedule</th>
                            <td>@_course.Schedule</td>
                        </tr>
                        <tr>
                            <th>Location</th>
                            <td>@_course.Location</td>
                        </tr>
                        <tr>
                            <th>Credits</th>
                            <td>@_course.Credits</td>
                        </tr>
                        <tr>
                            <th>Department</th>
                            <td>@_department?.Name (@_department?.Code)</td>
                        </tr>
                    </tbody>
                </table>

                <div class="mt-4">
                    <a href="/enroll?courseId=@_course.Id" class="btn btn-success btn-lg">Request Enrollment</a>
                    <a href="/courses" class="btn btn-outline-secondary btn-lg ms-2">← Back to Courses</a>
                </div>
            </div>

            <div class="col-lg-4 mt-4 mt-lg-0">
                @if (_instructor is not null)
                {
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">Instructor</h5>
                            <h6 class="mb-1">@_instructor.Name</h6>
                            <p class="text-body-secondary mb-2">@_instructor.Title</p>
                            <p class="card-text">@_instructor.Bio</p>
                            <a href="mailto:@_instructor.Email" class="btn btn-outline-primary btn-sm">
                                ✉ @_instructor.Email
                            </a>
                        </div>
                    </div>
                }
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private CourseCatalog.Models.Course? _course;
    private CourseCatalog.Models.Department? _department;
    private CourseCatalog.Models.Instructor? _instructor;

    protected override void OnInitialized()
    {
        _course = Catalog.GetCourse(Id);
        if (_course is not null)
        {
            _department = Catalog.GetDepartment(_course.DepartmentId);
            _instructor = Catalog.GetInstructor(_course.InstructorId);
        }
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CourseCatalogService Catalog

<PageTitle>Enrollment Request – University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for
                <strong>@_selectedCourseName</strong> has been received.</p>
            <p class="mb-0">You will receive a confirmation at your university email. Student ID: @_model.StudentId</p>
        </div>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        <a href="/enroll" class="btn btn-outline-secondary ms-2">Submit Another Request</a>
    }
    else
    {
        <div class="row">
            <div class="col-lg-8">
                <form method="post" data-enhance>
                    <AntiforgeryToken />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input type="text" id="studentName" name="Model.StudentName" value="@_model.StudentName"
                               class="form-control" required maxlength="100" />
                        @if (_errors.ContainsKey(nameof(_model.StudentName)))
                        {
                            <div class="text-danger small mt-1">@_errors[nameof(_model.StudentName)]</div>
                        }
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                        <input type="text" id="studentId" name="Model.StudentId" value="@_model.StudentId"
                               class="form-control" required maxlength="20" placeholder="e.g. STU-12345" />
                        @if (_errors.ContainsKey(nameof(_model.StudentId)))
                        {
                            <div class="text-danger small mt-1">@_errors[nameof(_model.StudentId)]</div>
                        }
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                        <select id="courseId" name="Model.CourseId" class="form-select" required>
                            <option value="">— Select a course —</option>
                            @foreach (var course in _courses)
                            {
                                <option value="@course.Id" selected="@(course.Id == _model.CourseId)">
                                    @course.Code – @course.Title (@course.Credits cr.)
                                </option>
                            }
                        </select>
                        @if (_errors.ContainsKey(nameof(_model.CourseId)))
                        {
                            <div class="text-danger small mt-1">@_errors[nameof(_model.CourseId)]</div>
                        }
                    </div>

                    <div class="mb-3">
                        <label for="notes" class="form-label">Additional Notes</label>
                        <textarea id="notes" name="Model.Notes" class="form-control" rows="3"
                                  maxlength="500">@_model.Notes</textarea>
                    </div>

                    <button type="submit" class="btn btn-success btn-lg">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-outline-secondary btn-lg ms-2">Cancel</a>
                </form>
            </div>
            <div class="col-lg-4 mt-4 mt-lg-0">
                <div class="card bg-light">
                    <div class="card-body">
                        <h5 class="card-title">ℹ️ How It Works</h5>
                        <ol class="mb-0 ps-3">
                            <li>Fill out the form with your details</li>
                            <li>Select the course you wish to enroll in</li>
                            <li>Submit your request</li>
                            <li>The registrar will review and confirm via email</li>
                        </ol>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

