    [SupplyParameterFromForm] public EnrollmentRequest? Model { get; set; }
    [SupplyParameterFromQuery] public int? CourseId { get; set; }
    [CascadingParameter] public HttpContext? HttpContext { get; set; }

    private EnrollmentRequest _model = new();
    private List<Course> _courses = new();
    private bool _submitted;
    private string _selectedCourseName = string.Empty;
    private Dictionary<string, string> _errors = new();

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        var isPost = HttpContext is not null && HttpMethods.IsPost(HttpContext.Request.Method);

        if (isPost && Model is not null)
        {
            _model = Model;
            _errors.Clear();
            var context = new System.ComponentModel.DataAnnotations.ValidationContext(_model);
            var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
            if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(_model, context, results, true))
            {
                foreach (var r in results)
                {
                    foreach (var member in r.MemberNames)
                    {
                        _errors.TryAdd(member, r.ErrorMessage ?? "Invalid");
                    }
                }
            }
            else
            {
